shell_commands:
python3 - <<'EOF'
p='src/orchestration/tools/registry.ts'
s=open(p).read()
s=s.replace("import {log} from '../../shared/logger.js';\n","import {Ajv} from 'ajv';\nimport {log} from '../../shared/logger.js';\n",1)
s=s.replace("""export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
""","""export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
""",1)
s=s.replace("""    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
""","""    const validate = this.ajv.compile(this.resolveDefinition(tool.definitionSource).inputSchema);
    if (!validate(input)) {
      const problems = (validate.errors ?? []).map(e => `${e.instancePath || '/'} ${e.message ?? 'is invalid'}`);
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for ${name}: ${problems.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
""",1)
open(p,'w').write(s)
EOF
NODE_OPTIONS=--experimental-vm-modules timeout 300 npx jest --runTestsByPath src/orchestration/tools/registry.test.ts 2>&1 | tail -8
